export const TECH_QUIZZES: Quiz[] = [
  { topic: "tech", level: "Easy", question: "What does 'CPU' stand for?", choices: ["Central Processing Unit", "Computer Personal Unit", "Central Program Utility", "Core Processing Underlay"], answer: 0, explain: "CPU = Central Processing Unit, the chip that executes instructions.", fact: "The first commercial microprocessor, Intel's 4004 (1971), packed about 2,300 transistors; modern CPUs hold tens of billions." },
  { topic: "tech", level: "Easy", question: "What does 'RAM' stand for?", choices: ["Rapid Access Memory", "Random Access Memory", "Read Always Memory", "Runtime Allocation Module"], answer: 1, explain: "RAM is Random Access Memory, volatile working memory.", fact: "RAM is volatile: cut the power and its contents vanish almost instantly, which is why unsaved work is lost in a crash." },
  { topic: "tech", level: "Easy", question: "What does 'HTML' primarily describe?", choices: ["A database", "A web page's structure", "A CPU design", "A network protocol"], answer: 1, explain: "HTML (HyperText Markup Language) structures web page content.", fact: "The very first web page, written in HTML by Tim Berners-Lee in 1991, is still online at CERN today." },
  { topic: "tech", level: "Easy", question: "Which company created the iPhone?", choices: ["Samsung", "Google", "Apple", "Nokia"], answer: 2, explain: "Apple released the first iPhone in 2007.", fact: "The original 2007 iPhone had no App Store, copy-paste, or third-party apps; the App Store arrived a year later in 2008." },
  { topic: "tech", level: "Easy", question: "What does 'URL' stand for?", choices: ["Uniform Resource Locator", "Universal Reference Link", "User Routing Layer", "Unified Retrieval Locator"], answer: 0, explain: "A URL is a Uniform Resource Locator, a web address.", fact: "The double slash after 'http:' was a design choice Tim Berners-Lee later admitted was unnecessary and would have dropped." },
  { topic: "tech", level: "Easy", question: "Which of these is an operating system?", choices: ["Photoshop", "Linux", "Chrome", "Excel"], answer: 1, explain: "Linux is an operating system; the others are applications.", fact: "Linux runs the majority of the world's web servers and powers Android, the most-used mobile OS on Earth." },
  { topic: "tech", level: "Easy", question: "What does 'Wi-Fi' let devices do?", choices: ["Store files", "Connect wirelessly to a network", "Cool the CPU", "Render graphics"], answer: 1, explain: "Wi-Fi provides wireless networking.", fact: "'Wi-Fi' is not short for 'Wireless Fidelity'; it was just a catchy brand name coined by a marketing firm." },
  { topic: "tech", level: "Easy", question: "Which company makes the Windows operating system?", choices: ["Apple", "IBM", "Microsoft", "Oracle"], answer: 2, explain: "Microsoft develops Windows.", fact: "Windows 1.0 shipped in 1985 and Microsoft supported it for over 16 years, retiring it only at the end of 2001." },
  { topic: "tech", level: "Easy", question: "What is the binary number system based on?", choices: ["Base 8", "Base 10", "Base 16", "Base 2"], answer: 3, explain: "Binary is base 2, using only 0 and 1.", fact: "Gottfried Leibniz described modern binary arithmetic in 1703, centuries before electronic computers existed." },
  { topic: "tech", level: "Easy", question: "What does 'GPU' stand for?", choices: ["General Processing Unit", "Graphics Processing Unit", "Global Power Unit", "Grid Performance Unit"], answer: 1, explain: "A GPU is a Graphics Processing Unit.", fact: "Though built for graphics, GPUs now drive most AI training because they perform thousands of math operations in parallel." },
  { topic: "tech", level: "Easy", question: "Which device converts digital signals to connect a home to the internet?", choices: ["Modem", "Monitor", "Keyboard", "Printer"], answer: 0, explain: "A modem modulates/demodulates signals for internet access.", fact: "The word 'modem' is a blend of 'modulator' and 'demodulator', describing exactly the two jobs it performs." },
  { topic: "tech", level: "Easy", question: "What does 'email' stand for?", choices: ["Electronic mail", "Encrypted mail", "Express mail", "External mail"], answer: 0, explain: "Email is short for electronic mail.", fact: "The first networked email was sent by Ray Tomlinson in 1971, and he chose the '@' symbol to separate user from host." },
  { topic: "tech", level: "Easy", question: "Which search engine is owned by Alphabet?", choices: ["Bing", "Yahoo", "Google", "DuckDuckGo"], answer: 2, explain: "Google is Alphabet's search engine.", fact: "'Google' is a play on 'googol', the number 1 followed by 100 zeros, reflecting its goal of indexing vast information." },
  { topic: "tech", level: "Easy", question: "What does 'USB' commonly connect?", choices: ["Power lines only", "Peripherals and storage devices", "Satellites", "Television antennas"], answer: 1, explain: "USB (Universal Serial Bus) connects peripherals and storage.", fact: "The original USB-A plug is famously unreversible, a quirk USB-C finally fixed by being symmetrical on both sides." },
  { topic: "tech", level: "Easy", question: "What is the most common image file format for photos on the web?", choices: ["EXE", "JPEG", "DOCX", "MP3"], answer: 1, explain: "JPEG is a widely used lossy photo format.", fact: "JPEG stands for the Joint Photographic Experts Group, the committee that standardized the format back in 1992." },
  { topic: "tech", level: "Easy", question: "Which programming language is named after a snake?", choices: ["Java", "Python", "Ruby", "Go"], answer: 1, explain: "Among these, Python is the one that shares a snake's name.", fact: "Python was actually named after the comedy troupe Monty Python, not the snake, by creator Guido van Rossum in 1991." },
  { topic: "tech", level: "Easy", question: "What does 'app' stand for?", choices: ["Applied program", "Application", "Appliance", "Appendix"], answer: 1, explain: "App is short for application.", fact: "'App' was named Word of the Year by the American Dialect Society in 2010, riding the smartphone boom." },
  { topic: "tech", level: "Easy", question: "Which company developed the Android operating system?", choices: ["Apple", "Google", "Microsoft", "Samsung"], answer: 1, explain: "Google develops Android.", fact: "Android began as an independent startup that Google quietly acquired in 2005 for a reported $50 million." },
  { topic: "tech", level: "Easy", question: "What does a firewall primarily do?", choices: ["Cool the computer", "Filter network traffic for security", "Speed up the CPU", "Store backups"], answer: 1, explain: "A firewall controls network traffic to protect systems.", fact: "The term borrows from building architecture, where a literal firewall is a barrier built to stop fire from spreading." },
  { topic: "tech", level: "Easy", question: "What unit measures digital storage capacity?", choices: ["Hertz", "Byte", "Volt", "Pixel"], answer: 1, explain: "Bytes (and their multiples) measure storage.", fact: "A byte is almost always 8 bits, but early computers used bytes of 6, 7, or even 9 bits before the 8-bit standard won out." },
  { topic: "tech", level: "Easy", question: "Which key combination commonly copies text in Windows?", choices: ["Ctrl+V", "Ctrl+C", "Ctrl+X", "Ctrl+Z"], answer: 1, explain: "Ctrl+C copies; Ctrl+V pastes.", fact: "The copy-cut-paste idea was pioneered by Larry Tesler at Xerox PARC in the 1970s; his car plate read 'NO MODES'." },
  { topic: "tech", level: "Easy", question: "What does 'SSD' stand for?", choices: ["Solid State Drive", "Secure Storage Disk", "System Service Daemon", "Static Storage Device"], answer: 0, explain: "SSD is a Solid State Drive, a flash-based storage device.", fact: "SSDs have no moving parts, so unlike spinning hard drives they make no noise and survive drops far better." },
  { topic: "tech", level: "Medium", question: "What does 'HTTP' stand for?", choices: ["HyperText Transfer Protocol", "High Transfer Text Process", "Hyperlink Text Transport Path", "Host Transfer Type Protocol"], answer: 0, explain: "HTTP is the HyperText Transfer Protocol used by the web.", fact: "The '404 Not Found' error is so iconic that some firms decorate physical room 404s as a tech in-joke." },
  { topic: "tech", level: "Medium", question: "Which data structure operates on a Last-In-First-Out basis?", choices: ["Queue", "Stack", "Linked list", "Tree"], answer: 1, explain: "A stack is LIFO; a queue is FIFO.", fact: "The 'call stack' that tracks running functions is a stack, which is why infinite recursion causes a 'stack overflow'." },
  { topic: "tech", level: "Medium", question: "Who is credited with proposing the World Wide Web in 1989?", choices: ["Vint Cerf", "Tim Berners-Lee", "Bill Gates", "Linus Torvalds"], answer: 1, explain: "Tim Berners-Lee invented the World Wide Web at CERN.", fact: "Berners-Lee gave the Web away royalty-free, choosing not to patent it so anyone could build on it openly." },
  { topic: "tech", level: "Medium", question: "What does 'SQL' stand for?", choices: ["Structured Query Language", "Sequential Query Logic", "System Quality Language", "Standard Quoted List"], answer: 0, explain: "SQL is Structured Query Language for relational databases.", fact: "SQL was originally called SEQUEL at IBM, but the name was shortened because another company already trademarked it." },
  { topic: "tech", level: "Medium", question: "In networking, what does 'DNS' do?", choices: ["Encrypts data", "Resolves domain names to IP addresses", "Routes electricity", "Compresses files"], answer: 1, explain: "DNS maps human-readable names to IP addresses.", fact: "DNS is often called 'the phone book of the internet', and a single misconfiguration can take huge sites offline." },
  { topic: "tech", level: "Medium", question: "Which company created the Linux kernel's original code in 1991?", choices: ["A team at Microsoft", "Linus Torvalds", "Richard Stallman", "AT&T Bell Labs"], answer: 1, explain: "Linus Torvalds wrote the original Linux kernel in 1991.", fact: "Torvalds was a 21-year-old student in Finland and famously announced it as 'just a hobby, won't be big and professional'." },
  { topic: "tech", level: "Medium", question: "What is the default port for HTTPS?", choices: ["80", "21", "443", "25"], answer: 2, explain: "HTTPS uses port 443 by default; HTTP uses 80.", fact: "There are 65,535 possible TCP ports, and the first 1,024 are reserved 'well-known' ports for standard services." },
  { topic: "tech", level: "Medium", question: "Which sorting algorithm has an average time complexity of O(n log n)?", choices: ["Bubble sort", "Insertion sort", "Merge sort", "Selection sort"], answer: 2, explain: "Merge sort runs in O(n log n); bubble/insertion/selection average O(n^2).", fact: "Merge sort was invented by computing pioneer John von Neumann back in 1945, one of the earliest algorithms described." },
  { topic: "tech", level: "Medium", question: "What does 'API' stand for?", choices: ["Application Programming Interface", "Applied Process Integration", "Automated Program Index", "Active Protocol Interface"], answer: 0, explain: "API is Application Programming Interface.", fact: "Public APIs power the 'API economy': apps like ride-sharing and weather widgets are largely glued-together API calls." },
  { topic: "tech", level: "Medium", question: "Which protocol is used to send email between servers?", choices: ["FTP", "SMTP", "SNMP", "POP3"], answer: 1, explain: "SMTP (Simple Mail Transfer Protocol) sends mail; POP3/IMAP retrieve it.", fact: "SMTP dates to 1981 and originally had no built-in security, which is why spam and spoofing became such persistent problems." },
  { topic: "tech", level: "Medium", question: "What does 'RAID' help provide for storage?", choices: ["Faster internet", "Redundancy and/or performance", "Lower power use", "Better graphics"], answer: 1, explain: "RAID combines disks for redundancy and/or performance.", fact: "RAID originally stood for 'Redundant Array of Inexpensive Disks', coined by researchers at UC Berkeley in 1987." },
  { topic: "tech", level: "Medium", question: "In Git, which command creates a snapshot of staged changes?", choices: ["git push", "git clone", "git commit", "git fetch"], answer: 2, explain: "git commit records staged changes to the repository.", fact: "Linus Torvalds built Git in 2005 in just a couple of weeks after a falling-out over the Linux project's old tooling." },
  { topic: "tech", level: "Medium", question: "Which company developed the Java programming language?", choices: ["Microsoft", "Sun Microsystems", "IBM", "Apple"], answer: 1, explain: "Java was created by Sun Microsystems in 1995.", fact: "Java was first named 'Oak' after a tree outside the developer's office before trademark issues forced the rename." },
  { topic: "tech", level: "Medium", question: "What is the maximum value of a single unsigned 8-bit byte?", choices: ["127", "256", "255", "128"], answer: 2, explain: "An 8-bit unsigned value ranges 0-255 (2^8 - 1).", fact: "This 0-255 range is why color values in web design (like RGB codes) max out at 255 per channel." },
  { topic: "tech", level: "Medium", question: "Which of these is a NoSQL database?", choices: ["PostgreSQL", "MongoDB", "MySQL", "SQLite"], answer: 1, explain: "MongoDB is a document-oriented NoSQL database.", fact: "MongoDB's name comes from 'humongous', reflecting its design goal of handling huge volumes of data." },
  { topic: "tech", level: "Medium", question: "What does the 'cloud' generally refer to in computing?", choices: ["Weather data systems", "On-demand remote servers and services", "A type of CPU", "Local hard drives"], answer: 1, explain: "Cloud computing delivers compute/storage over the internet.", fact: "The cloud symbol came from old network diagrams, where engineers drew a cloud to mean 'the messy part out there'." },
  { topic: "tech", level: "Medium", question: "Which encryption approach uses a public and a private key?", choices: ["Symmetric encryption", "Asymmetric encryption", "Hashing", "Compression"], answer: 1, explain: "Asymmetric (public-key) encryption uses a key pair.", fact: "Public-key cryptography was published by Diffie and Hellman in 1976, solving the age-old problem of sharing secret keys." },
  { topic: "tech", level: "Medium", question: "What does 'IoT' stand for?", choices: ["Internet of Things", "Index of Tables", "Input output Transfer", "Integration of Tools"], answer: 0, explain: "IoT is the Internet of Things, networked physical devices.", fact: "An early IoT device was a Carnegie Mellon Coke machine in the 1980s that reported online whether drinks were cold." },
  { topic: "tech", level: "Medium", question: "Which famous duo founded Apple in 1976?", choices: ["Gates and Allen", "Jobs and Wozniak", "Page and Brin", "Hewlett and Packard"], answer: 1, explain: "Steve Jobs and Steve Wozniak co-founded Apple (with Ronald Wayne).", fact: "Third co-founder Ronald Wayne sold his 10% stake for $800 in 1976; it would later be worth tens of billions." },
  { topic: "tech", level: "Medium", question: "What does a compiler do?", choices: ["Runs code line by line", "Translates source code into machine code", "Stores data", "Connects to the network"], answer: 1, explain: "A compiler translates source code into executable machine code.", fact: "Grace Hopper built the first compiler in the early 1950s; many doubted a computer could even write its own programs." },
  { topic: "tech", level: "Medium", question: "Which layer of the OSI model handles IP addressing and routing?", choices: ["Transport layer", "Network layer", "Data link layer", "Application layer"], answer: 1, explain: "The network (layer 3) handles IP addressing and routing.", fact: "The OSI model has seven layers, often memorized with the mnemonic 'Please Do Not Throw Sausage Pizza Away'." },
  { topic: "tech", level: "Medium", question: "What is the term for a self-replicating malicious program that spreads without user action?", choices: ["Trojan", "Worm", "Spyware", "Adware"], answer: 1, explain: "A worm self-replicates and spreads across networks autonomously.", fact: "The 1988 Morris Worm, one of the first, infected thousands of machines and led to the first U.S. cybercrime conviction." },
  { topic: "tech", level: "Medium", question: "Which company acquired GitHub in 2018?", choices: ["Google", "Microsoft", "Amazon", "Meta"], answer: 1, explain: "Microsoft acquired GitHub in 2018.", fact: "Microsoft paid about $7.5 billion in stock, a striking turn given it once called open source a threat to its business." },
  { topic: "tech", level: "Hard", question: "What is the time complexity of searching a balanced binary search tree?", choices: ["O(1)", "O(n)", "O(log n)", "O(n log n)"], answer: 2, explain: "A balanced BST gives O(log n) search by halving the range each step.", fact: "Self-balancing trees like AVL and red-black trees automatically rotate nodes to keep that O(log n) guarantee intact." },
  { topic: "tech", level: "Hard", question: "In the CAP theorem, which three properties can a distributed system not all guarantee simultaneously?", choices: ["Consistency, Availability, Partition tolerance", "Concurrency, Atomicity, Persistence", "Caching, Allocation, Pipelining", "Capacity, Accuracy, Performance"], answer: 0, explain: "CAP = Consistency, Availability, Partition tolerance; you can guarantee at most two.", fact: "The CAP theorem was conjectured by Eric Brewer in 2000 and formally proven by MIT researchers two years later." },
  { topic: "tech", level: "Hard", question: "Which consensus algorithm is used by the Raft protocol to elect a leader?", choices: ["Proof of work", "Randomized election timeouts with majority votes", "Round-robin scheduling", "Shortest path first"], answer: 1, explain: "Raft uses randomized timeouts so a candidate wins with a majority of votes.", fact: "Raft was explicitly designed to be easier to understand than the older Paxos algorithm, which is notoriously hard to grasp." },
  { topic: "tech", level: "Hard", question: "What does the acronym 'ACID' guarantee in databases?", choices: ["Atomicity, Consistency, Isolation, Durability", "Availability, Caching, Indexing, Distribution", "Access, Control, Integrity, Defense", "Allocation, Concurrency, Indexing, Durability"], answer: 0, explain: "ACID = Atomicity, Consistency, Isolation, Durability for transactions.", fact: "The 'A' for atomicity means a transaction is all-or-nothing, like a bank transfer that never debits without crediting." },
  { topic: "tech", level: "Hard", question: "In computer architecture, what does a TLB (Translation Lookaside Buffer) cache?", choices: ["Recently used disk blocks", "Virtual-to-physical address translations", "Branch prediction history", "Instruction opcodes"], answer: 1, explain: "A TLB caches page-table virtual-to-physical address mappings.", fact: "A 'TLB miss' forces a slow page-table walk, so the TLB's hit rate is one of the quiet keys to fast memory access." },
  { topic: "tech", level: "Hard", question: "Which complexity class contains problems verifiable in polynomial time?", choices: ["P", "NP", "EXPTIME", "PSPACE"], answer: 1, explain: "NP is the class of problems whose solutions are verifiable in polynomial time.", fact: "Whether P equals NP is one of the seven Millennium Prize Problems, with a $1 million reward for a proof either way." },
  { topic: "tech", level: "Hard", question: "What does TCP's 'three-way handshake' consist of?", choices: ["SYN, SYN-ACK, ACK", "GET, POST, PUT", "PING, PONG, CLOSE", "OPEN, READ, WRITE"], answer: 0, explain: "TCP opens a connection with SYN, SYN-ACK, then ACK.", fact: "TCP also has a four-step teardown sequence to politely close a connection, ensuring no in-flight data is lost." },
  { topic: "tech", level: "Hard", question: "In cryptography, what property makes a hash function 'collision resistant'?", choices: ["Output length grows with input", "It is hard to find two inputs with the same output", "It can be reversed quickly", "It uses a public key"], answer: 1, explain: "Collision resistance means finding two distinct inputs hashing to the same value is infeasible.", fact: "Researchers broke SHA-1's collision resistance in 2017 with an attack dubbed SHAttered, hastening its retirement." },
  { topic: "tech", level: "Hard", question: "Which scheduling problem does the 'dining philosophers' classically illustrate?", choices: ["Cache invalidation", "Deadlock and resource contention", "Memory fragmentation", "Floating-point rounding"], answer: 1, explain: "The dining philosophers problem illustrates deadlock and resource starvation.", fact: "Edsger Dijkstra posed the puzzle in 1965, originally framing it as computers competing for tape drives, not philosophers." },
  { topic: "tech", level: "Hard", question: "What is 'memoization' in dynamic programming?", choices: ["Compressing memory pages", "Caching results of expensive function calls", "Encrypting variables", "Garbage collecting unused objects"], answer: 1, explain: "Memoization stores subproblem results to avoid recomputation.", fact: "The term was coined by Donald Michie in 1968 from the Latin 'memorandum', meaning 'to be remembered'." },
  { topic: "tech", level: "Hard", question: "In the context of CPUs, what does 'speculative execution' do?", choices: ["Runs instructions before knowing if they are needed", "Encrypts the instruction stream", "Compresses cache lines", "Disables interrupts"], answer: 0, explain: "Speculative execution runs likely-needed instructions ahead of branch resolution.", fact: "Speculative execution caused the 2018 Spectre and Meltdown flaws, leaking secrets across nearly every modern CPU." },
  { topic: "tech", level: "Hard", question: "Which data structure underlies a typical hash table to resolve collisions via 'chaining'?", choices: ["Binary heap", "Linked list per bucket", "Red-black tree only", "Circular buffer"], answer: 1, explain: "Separate chaining stores colliding entries in a linked list per bucket.", fact: "Java's HashMap upgrades long collision chains into balanced trees once a bucket grows past eight entries, for speed." },
  { topic: "tech", level: "Hard", question: "What does 'idempotent' mean for an HTTP method like PUT?", choices: ["It must use HTTPS", "Repeating the request has the same effect as one request", "It always returns cached data", "It cannot have a body"], answer: 1, explain: "An idempotent operation yields the same result no matter how many times it is repeated.", fact: "Pressing a calculator's '=' key is idempotent; pressing '+5' is not, which is the everyday intuition behind the term." },
  { topic: "tech", level: "Hard", question: "In machine learning, what problem does 'gradient descent' aim to solve?", choices: ["Sorting data", "Minimizing a loss function", "Encrypting weights", "Allocating memory"], answer: 1, explain: "Gradient descent iteratively adjusts parameters to minimize a loss function.", fact: "It is often pictured as walking downhill in fog, taking steps in the steepest downward direction toward a valley." },
  { topic: "tech", level: "Hard", question: "Which feature distinguishes a 'monad' in functional programming?", choices: ["It mutates global state", "It provides a way to chain computations with context", "It guarantees O(1) memory", "It compiles to assembly directly"], answer: 1, explain: "A monad structures and chains computations carrying a context (e.g. effects, optionality).", fact: "A running joke calls a monad 'a monoid in the category of endofunctors', a phrase meant to sound impenetrable." },
  { topic: "tech", level: "Hard", question: "What does 'two-phase commit' coordinate in distributed databases?", choices: ["Load balancing", "Atomic commit across multiple nodes", "Index rebuilding", "Cache warming"], answer: 1, explain: "Two-phase commit ensures all participating nodes commit or abort atomically.", fact: "Two-phase commit can block forever if the coordinator crashes mid-protocol, which is why three-phase variants exist." },
];

export const ECONOMICS_QUIZZES: Quiz[] = [
  { topic: "economics", level: "Easy", question: "What does 'GDP' stand for?", choices: ["Gross Domestic Product", "General Domestic Price", "Global Demand Power", "Gross Demand Percentage"], answer: 0, explain: "GDP is Gross Domestic Product, the total value of goods and services produced.", fact: "GDP was developed by economist Simon Kuznets in the 1930s, who warned it should not be mistaken for a measure of well-being." },
  { topic: "economics", level: "Easy", question: "What is inflation?", choices: ["A drop in wages", "A general rise in prices over time", "An increase in exports", "A fall in interest rates"], answer: 1, explain: "Inflation is a sustained general increase in prices.", fact: "Hyperinflation in 1920s Germany got so bad that people burned banknotes for heat because they were cheaper than firewood." },
  { topic: "economics", level: "Easy", question: "What is the currency of Japan?", choices: ["Won", "Yuan", "Yen", "Ringgit"], answer: 2, explain: "Japan's currency is the yen.", fact: "The word 'yen' means 'round object', referring to the round coins introduced when Japan modernized its money in 1871." },
  { topic: "economics", level: "Easy", question: "What does 'supply and demand' help determine?", choices: ["Tax rates only", "Market prices", "Population growth", "Weather patterns"], answer: 1, explain: "The interaction of supply and demand sets market prices.", fact: "The famous intersecting supply-and-demand curves were popularized by Alfred Marshall in his 1890 economics textbook." },
  { topic: "economics", level: "Easy", question: "What is a budget surplus?", choices: ["Spending more than income", "Income equal to spending", "Income exceeding spending", "Borrowing money"], answer: 2, explain: "A surplus occurs when income exceeds spending.", fact: "National budget surpluses are rare; the U.S. federal government last ran one in the years around 2000." },
  { topic: "economics", level: "Easy", question: "Which institution typically sets a country's interest rates?", choices: ["The central bank", "The stock exchange", "The post office", "The supreme court"], answer: 0, explain: "Central banks set benchmark interest rates.", fact: "Sweden's Riksbank, founded in 1668, is generally considered the world's oldest central bank still operating today." },
  { topic: "economics", level: "Easy", question: "What is a stock?", choices: ["A loan to a company", "A share of ownership in a company", "A government tax", "A type of currency"], answer: 1, explain: "A stock represents partial ownership of a company.", fact: "The Dutch East India Company issued the first publicly traded shares in 1602, making it a pioneer of the modern stock market." },
  { topic: "economics", level: "Easy", question: "What is the currency used across much of the European Union?", choices: ["Pound", "Franc", "Euro", "Mark"], answer: 2, explain: "The euro is used by eurozone member states.", fact: "Euro banknotes show fictional bridges and windows so no single country's real landmarks could claim favoritism." },
  { topic: "economics", level: "Easy", question: "What does 'interest' on a savings account represent?", choices: ["A fee you pay the bank", "Money the bank pays you for deposits", "A tax", "An exchange rate"], answer: 1, explain: "Interest is what the bank pays you for holding your deposit.", fact: "Banks lend out most of the money you deposit, paying you a slice of interest while charging borrowers much more." },
  { topic: "economics", level: "Easy", question: "What is a recession commonly defined as?", choices: ["Rising stock prices", "A significant, broad decline in economic activity", "A government election", "A rise in exports"], answer: 1, explain: "A recession is a significant, widespread decline in economic activity.", fact: "A popular rule of thumb calls two straight quarters of shrinking GDP a recession, though official bodies use broader criteria." },
  { topic: "economics", level: "Easy", question: "What does 'profit' mean for a business?", choices: ["Total sales", "Revenue minus costs", "Number of employees", "Amount of debt"], answer: 1, explain: "Profit is revenue left after subtracting costs.", fact: "A business can post soaring revenue yet still lose money; many fast-growing startups run at a loss for years on purpose." },
  { topic: "economics", level: "Easy", question: "What is a bond?", choices: ["A share of ownership", "A loan you make to a government or company", "A type of tax", "A bank account"], answer: 1, explain: "A bond is a debt security; you lend money for interest.", fact: "Some governments have issued ultra-long bonds, and Austria has even sold debt that matures a full century later." },
  { topic: "economics", level: "Easy", question: "What does 'unemployment rate' measure?", choices: ["People without jobs who are seeking work", "Total population", "Number of businesses", "Average wages"], answer: 0, explain: "It measures the share of the labor force jobless but seeking work.", fact: "People who give up looking for work aren't counted as unemployed, so the headline rate can understate true joblessness." },
  { topic: "economics", level: "Easy", question: "What is bartering?", choices: ["Paying with credit cards", "Exchanging goods or services without money", "Saving in a bank", "Investing in stocks"], answer: 1, explain: "Bartering trades goods/services directly without currency.", fact: "Barter's weakness, the 'double coincidence of wants', is exactly the problem money was invented to solve." },
  { topic: "economics", level: "Easy", question: "What is a 'monopoly' in economics?", choices: ["Many competing sellers", "A single seller dominating a market", "A type of tax", "A stock exchange"], answer: 1, explain: "A monopoly is a market dominated by a single seller.", fact: "The board game Monopoly grew from 'The Landlord's Game', designed to criticize the harms of real-world land monopolies." },
  { topic: "economics", level: "Easy", question: "What does 'export' mean?", choices: ["Buying goods from abroad", "Selling goods to other countries", "Printing money", "Raising taxes"], answer: 1, explain: "Exports are goods/services sold to other countries.", fact: "Services like tourism, software, and consulting count as exports too, not just physical goods shipped overseas." },
  { topic: "economics", level: "Easy", question: "What is the currency of the United Kingdom?", choices: ["Euro", "Dollar", "Pound sterling", "Krona"], answer: 2, explain: "The UK uses the pound sterling.", fact: "The pound sterling is the world's oldest currency still in use, with roots stretching back over 1,200 years." },
  { topic: "economics", level: "Easy", question: "What is a 'tax'?", choices: ["A voluntary donation", "A compulsory payment to the government", "A bank loan", "A company dividend"], answer: 1, explain: "A tax is a mandatory payment levied by the government.", fact: "England once taxed windows, prompting owners to brick them up, which is thought to be the origin of 'daylight robbery'." },
  { topic: "economics", level: "Easy", question: "What does 'income' mean?", choices: ["Money received, e.g. from work", "Money spent", "Debt owed", "Taxes paid"], answer: 0, explain: "Income is money received, such as wages or returns.", fact: "Economists split income into 'earned' (from work) and 'passive' (from assets like rent, dividends, or interest)." },
  { topic: "economics", level: "Easy", question: "What is the stock market?", choices: ["A place to buy groceries", "A marketplace for buying and selling shares", "A government office", "A bank branch"], answer: 1, explain: "The stock market is where shares are bought and sold.", fact: "The New York Stock Exchange traces back to the 1792 Buttonwood Agreement, signed by brokers under a buttonwood tree." },
  { topic: "economics", level: "Easy", question: "What does 'savings' refer to?", choices: ["Money you spend immediately", "Income not spent and set aside", "Money you borrow", "Taxes you owe"], answer: 1, explain: "Savings is income kept rather than spent.", fact: "The 'paradox of thrift' notes that if everyone saves more at once, total spending and incomes can actually fall." },
  { topic: "economics", level: "Easy", question: "What is 'currency'?", choices: ["A type of tax", "A system of money in general use", "A government bond", "A stock dividend"], answer: 1, explain: "Currency is money in circulation as a medium of exchange.", fact: "The Pacific island of Yap famously used giant carved stone discs, some too heavy to move, as a form of currency." },
  { topic: "economics", level: "Medium", question: "What does the 'invisible hand' metaphor describe?", choices: ["Government price controls", "Self-interest guiding markets toward beneficial outcomes", "Central bank intervention", "Tax collection"], answer: 1, explain: "Adam Smith's invisible hand: individual self-interest can benefit society via markets.", fact: "Adam Smith used the phrase only a handful of times across his works, yet it became the symbol of free-market thought." },
  { topic: "economics", level: "Medium", question: "What is fiscal policy?", choices: ["A central bank's control of money supply", "Government use of spending and taxation", "Setting exchange rates", "Regulating stock exchanges"], answer: 1, explain: "Fiscal policy is government spending and taxation; monetary policy is the central bank's tool.", fact: "The word 'fiscal' comes from the Latin 'fiscus', meaning a basket or purse used to hold public money." },
  { topic: "economics", level: "Medium", question: "Who wrote 'The Wealth of Nations' (1776)?", choices: ["John Maynard Keynes", "Karl Marx", "Adam Smith", "David Ricardo"], answer: 2, explain: "Adam Smith authored The Wealth of Nations, a foundational economics text.", fact: "Smith was actually a moral philosophy professor, and his earlier book explored human empathy, not markets." },
  { topic: "economics", level: "Medium", question: "What does 'GDP per capita' measure?", choices: ["Total exports", "Economic output divided by population", "The inflation rate", "Government debt"], answer: 1, explain: "GDP per capita is GDP divided by population, a rough living-standard proxy.", fact: "Tiny financial hubs like Luxembourg and Monaco often top GDP-per-capita rankings, well ahead of far larger economies." },
  { topic: "economics", level: "Medium", question: "What is a 'bull market'?", choices: ["A market with falling prices", "A market with rising prices", "A market that is closed", "A government bond market"], answer: 1, explain: "A bull market trends upward; a bear market trends downward.", fact: "One theory says the names come from how each animal attacks: a bull thrusts up with its horns, a bear swipes down." },
  { topic: "economics", level: "Medium", question: "What is 'opportunity cost'?", choices: ["The price of an item", "The value of the next-best alternative forgone", "A type of tax", "Total revenue"], answer: 1, explain: "Opportunity cost is the value of what you give up by choosing one option.", fact: "Even free things have opportunity cost: a 'free' two-hour movie costs whatever else you could have done with that time." },
  { topic: "economics", level: "Medium", question: "Which economist is most associated with advocating government spending to fight recessions?", choices: ["Milton Friedman", "John Maynard Keynes", "Friedrich Hayek", "Adam Smith"], answer: 1, explain: "Keynes argued for government demand stimulus during downturns.", fact: "Keynes was also a savvy investor who made and lost fortunes, managing his Cambridge college's endowment for decades." },
  { topic: "economics", level: "Medium", question: "What does the 'law of demand' state?", choices: ["As price rises, quantity demanded falls, all else equal", "As price rises, demand rises", "Demand is fixed regardless of price", "Demand depends only on supply"], answer: 0, explain: "The law of demand: higher prices generally reduce quantity demanded.", fact: "Rare 'Giffen goods', often staple foods for the very poor, can defy the law and sell more as their price climbs." },
  { topic: "economics", level: "Medium", question: "What is a 'dividend'?", choices: ["Interest on a loan", "A share of profits paid to shareholders", "A government tax", "A bond's face value"], answer: 1, explain: "A dividend is a distribution of company profits to shareholders.", fact: "Some companies, called 'dividend aristocrats', have raised their dividend every year for at least 25 years straight." },
  { topic: "economics", level: "Medium", question: "What does a country's 'trade deficit' mean?", choices: ["Exports exceed imports", "Imports exceed exports", "Balanced trade", "No international trade"], answer: 1, explain: "A trade deficit means imports exceed exports.", fact: "A trade deficit isn't automatically bad; it often reflects strong consumer demand and inflows of foreign investment." },
  { topic: "economics", level: "Medium", question: "What is 'monetary policy'?", choices: ["Government taxation", "Central bank management of money supply and interest rates", "Setting trade tariffs", "Regulating wages"], answer: 1, explain: "Monetary policy is the central bank's control of money supply and rates.", fact: "Central banks influence the whole economy by nudging a single overnight rate that ripples out to loans and savings." },
  { topic: "economics", level: "Medium", question: "What was the approximate cause of the 1929 Wall Street Crash that preceded the Great Depression?", choices: ["A speculative stock bubble bursting", "A new gold standard", "A trade surplus", "Rapid deflation only"], answer: 0, explain: "Excessive speculation and a stock bubble collapse triggered the 1929 crash.", fact: "Many investors had bought stocks 'on margin' with borrowed money, so the crash wiped them out and amplified the fall." },
  { topic: "economics", level: "Medium", question: "What is 'GDP' adjusted for inflation called?", choices: ["Nominal GDP", "Real GDP", "Gross national income", "Net exports"], answer: 1, explain: "Real GDP is inflation-adjusted; nominal GDP is not.", fact: "Without adjusting for inflation, an economy could look like it's 'growing' even when it's actually producing less." },
  { topic: "economics", level: "Medium", question: "What is a 'progressive tax'?", choices: ["A flat rate for everyone", "A tax where the rate rises with income", "A tax only on goods", "A tax on exports"], answer: 1, explain: "A progressive tax charges higher rates on higher incomes.", fact: "Its opposite, a 'regressive tax', takes a bigger share from the poor; sales taxes often work this way in practice." },
  { topic: "economics", level: "Medium", question: "What does 'liquidity' refer to in finance?", choices: ["A company's total debt", "How easily an asset converts to cash", "The inflation rate", "A type of bond"], answer: 1, explain: "Liquidity is how quickly an asset can be turned into cash without loss.", fact: "Cash is the most liquid asset of all, while things like real estate or fine art can take months or years to sell." },
  { topic: "economics", level: "Medium", question: "What is 'comparative advantage'?", choices: ["Producing everything cheaper than rivals", "Producing a good at a lower opportunity cost than others", "Having the largest economy", "Charging the highest prices"], answer: 1, explain: "Comparative advantage is producing at a lower opportunity cost, underpinning trade gains.", fact: "David Ricardo introduced the idea in 1817, showing countries gain from trade even if one is better at making everything." },
  { topic: "economics", level: "Medium", question: "What is a 'central bank' lender of last resort role?", choices: ["Printing money for citizens", "Providing emergency funds to banks in crisis", "Collecting income tax", "Setting company wages"], answer: 1, explain: "As lender of last resort, a central bank supplies liquidity to banks during crises.", fact: "The idea was spelled out by journalist Walter Bagehot in 1873: lend freely, at a penalty rate, on good collateral." },
  { topic: "economics", level: "Medium", question: "What does 'CPI' measure?", choices: ["Company profit index", "Consumer Price Index, tracking average prices", "Central policy interest", "Capital production input"], answer: 1, explain: "CPI is the Consumer Price Index, a common inflation measure.", fact: "CPI tracks a fixed 'basket' of goods and services, which statisticians periodically update to match changing habits." },
  { topic: "economics", level: "Medium", question: "What is 'gross' versus 'net' income?", choices: ["Gross is after taxes, net is before", "Gross is before deductions, net is after", "They are identical", "Net includes only bonuses"], answer: 1, explain: "Gross income is before deductions; net income is what remains after them.", fact: "'Net' comes from an old word for 'clean' or 'pure', meaning the amount left clean after everything is taken out." },
  { topic: "economics", level: "Medium", question: "Which crisis is associated with the collapse of Lehman Brothers in 2008?", choices: ["The dot-com bust", "The global financial crisis", "The 1970s oil crisis", "The Asian financial crisis"], answer: 1, explain: "Lehman's 2008 collapse was a flashpoint of the global financial crisis.", fact: "Lehman Brothers was 158 years old and its bankruptcy remains the largest in U.S. history by assets involved." },
  { topic: "economics", level: "Medium", question: "What is an 'exchange rate'?", choices: ["A stock's price", "The price of one currency in terms of another", "A tax on imports", "A central bank reserve"], answer: 1, explain: "An exchange rate is the value of one currency relative to another.", fact: "The Economist's tongue-in-cheek 'Big Mac Index' compares burger prices worldwide to gauge if currencies are mispriced." },
  { topic: "economics", level: "Medium", question: "What does 'diversification' aim to reduce in investing?", choices: ["Returns", "Risk", "Taxes", "Liquidity"], answer: 1, explain: "Diversifying across assets reduces portfolio risk.", fact: "Economist Harry Markowitz called diversification 'the only free lunch in finance' and won a Nobel Prize for the idea." },
  { topic: "economics", level: "Medium", question: "What is a 'subsidy'?", choices: ["A tax on producers", "Government financial support to lower a good's cost", "A type of tariff", "A bank loan"], answer: 1, explain: "A subsidy is government support that lowers costs or prices.", fact: "Governments spend hundreds of billions yearly subsidizing things like agriculture and energy to steer the economy." },
  { topic: "economics", level: "Hard", question: "What does 'elasticity of demand' specifically measure?", choices: ["Total revenue", "Responsiveness of quantity demanded to a price change", "The inflation rate", "A firm's market share"], answer: 1, explain: "Price elasticity of demand measures the percentage change in quantity demanded per percentage change in price.", fact: "Demand for addictive or essential goods like insulin is highly 'inelastic', barely budging even when prices jump." },
  { topic: "economics", level: "Hard", question: "In the Phillips curve, what relationship is traditionally described?", choices: ["Inflation and unemployment tend to move inversely", "GDP and exports move together", "Interest rates and savings are unrelated", "Wages and taxes move together"], answer: 0, explain: "The traditional Phillips curve posits an inverse short-run relation between inflation and unemployment.", fact: "The 1970s stagflation, with high inflation and high unemployment together, badly challenged the Phillips curve." },
  { topic: "economics", level: "Hard", question: "What is 'quantitative easing'?", choices: ["Raising taxes broadly", "A central bank buying assets to inject money into the economy", "Cutting government jobs", "Devaluing currency by decree"], answer: 1, explain: "QE is a central bank purchasing assets (e.g. bonds) to expand the money supply and lower long-term rates.", fact: "Japan pioneered modern QE in the early 2000s, and it went global after central banks ran out of room to cut rates in 2008." },
  { topic: "economics", level: "Hard", question: "What does the 'Gini coefficient' measure?", choices: ["Inflation volatility", "Income or wealth inequality", "Trade balance", "Money velocity"], answer: 1, explain: "The Gini coefficient measures inequality from 0 (perfect equality) to 1 (maximal inequality).", fact: "It was devised by Italian statistician Corrado Gini in 1912 and is now the world's go-to inequality yardstick." },
  { topic: "economics", level: "Hard", question: "In game theory, what characterizes a 'Nash equilibrium'?", choices: ["Everyone earns equal payoffs", "No player can gain by unilaterally changing strategy", "The market clears at one price", "All players cooperate"], answer: 1, explain: "At a Nash equilibrium no player benefits from changing strategy alone, given others' choices.", fact: "John Nash's work won a 1994 Nobel and inspired the film 'A Beautiful Mind' about his life and struggles." },
  { topic: "economics", level: "Hard", question: "What is 'stagflation'?", choices: ["High growth with low inflation", "Stagnant growth combined with high inflation", "Falling prices and rising output", "A balanced budget"], answer: 1, explain: "Stagflation pairs stagnant growth and high unemployment with high inflation.", fact: "The term blends 'stagnation' and 'inflation' and was coined by a British politician during the troubled 1960s." },
  { topic: "economics", level: "Hard", question: "What does the 'velocity of money' refer to in the equation MV = PQ?", choices: ["The speed of stock trades", "The rate at which money changes hands in the economy", "The growth of exports", "The central bank's interest rate"], answer: 1, explain: "Velocity (V) is how frequently a unit of money is spent over a period in the quantity theory MV = PQ.", fact: "Money velocity tends to plunge in crises as people hoard cash, which can blunt the boost from printing more money." },
  { topic: "economics", level: "Hard", question: "Which concept describes a cost imposed on third parties not reflected in market prices?", choices: ["Opportunity cost", "Negative externality", "Sunk cost", "Marginal cost"], answer: 1, explain: "A negative externality is a cost borne by third parties, like pollution, outside the price.", fact: "Carbon taxes and cap-and-trade are attempts to 'internalize' the externality of pollution by putting a price on it." },
  { topic: "economics", level: "Hard", question: "What is the 'liquidity trap' associated with Keynesian economics?", choices: ["When interest rates are so low that monetary policy loses traction", "When banks run out of cash", "When exports collapse", "When taxes exceed income"], answer: 0, explain: "In a liquidity trap, rates near zero make additional money injection ineffective at boosting demand.", fact: "Japan's decades of near-zero rates after the 1990s became the textbook real-world example of a liquidity trap." },
  { topic: "economics", level: "Hard", question: "What does 'purchasing power parity' (PPP) attempt to do?", choices: ["Set interest rates", "Compare currencies by equalizing the price of a basket of goods", "Measure unemployment", "Fix exchange rates by law"], answer: 1, explain: "PPP compares currencies based on the cost of an equivalent basket of goods across countries.", fact: "By PPP measures, China overtook the U.S. as the world's largest economy around 2014, though not at market exchange rates." },
  { topic: "economics", level: "Hard", question: "What is 'moral hazard' in finance?", choices: ["Insider trading", "Taking more risk because one is shielded from its consequences", "Defaulting on a loan", "A type of tax fraud"], answer: 1, explain: "Moral hazard arises when a party takes on more risk because someone else bears the downside.", fact: "Critics argue bank bailouts breed moral hazard by signaling that risky firms will be rescued if they grow large enough." },
  { topic: "economics", level: "Hard", question: "Which economist is most associated with monetarism and the idea that 'inflation is always a monetary phenomenon'?", choices: ["John Maynard Keynes", "Milton Friedman", "Paul Samuelson", "Joseph Stiglitz"], answer: 1, explain: "Milton Friedman championed monetarism and that famous statement on inflation.", fact: "Friedman was a popular communicator too, hosting the 1980 TV series 'Free to Choose' to make economics mainstream." },
  { topic: "economics", level: "Hard", question: "What is a 'deadweight loss'?", choices: ["A firm's fixed costs", "Lost economic efficiency when equilibrium is not achieved, e.g. due to a tax", "A drop in GDP", "Unsold inventory"], answer: 1, explain: "Deadweight loss is the efficiency loss when a market is distorted from its competitive equilibrium.", fact: "An economics paper once estimated the 'deadweight loss of Christmas' from gifts recipients value less than they cost." },
  { topic: "economics", level: "Hard", question: "What does the 'efficient market hypothesis' claim?", choices: ["Markets always rise over time", "Asset prices fully reflect all available information", "Governments set fair prices", "Diversification eliminates all risk"], answer: 1, explain: "The EMH holds that prices incorporate all available information, making it hard to beat the market consistently.", fact: "Eugene Fama, who formalized the EMH, shared a 2013 Nobel with Robert Shiller, a leading skeptic of the idea." },
  { topic: "economics", level: "Hard", question: "In macroeconomics, what is the 'crowding out' effect?", choices: ["Private investment falling as government borrowing raises interest rates", "Too many firms entering a market", "Excess consumer spending", "Currency devaluation"], answer: 0, explain: "Crowding out occurs when increased government borrowing pushes up rates and reduces private investment.", fact: "Economists still debate how strong crowding out is in a slump, when idle resources may leave plenty of room to borrow." },
  { topic: "economics", level: "Hard", question: "What is 'seigniorage'?", choices: ["A tax on luxury goods", "Profit a government makes from issuing currency", "Interest paid on bonds", "A type of tariff"], answer: 1, explain: "Seigniorage is the revenue a government earns from creating money beyond its production cost.", fact: "A penny can cost more than one cent to mint, meaning some small coins actually generate negative seigniorage." },
];

